  app.get("/api/clinical-documentation/notes/:id/context", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const note = await storage.getClinicalNoteById((req.params as any).id);
      if (!note) {
        return res.status(404).json({ error: "Note not found" });
      }
      if (note.providerId !== userId) {
        return res.status(403).json({ error: "Access denied" });
      }
      const aiContent = note.aiGeneratedContent as any;
      const contextData: any = {
        noteId: note.id,
        noteType: note.noteType,
        status: note.status,
        createdAt: note.createdAt,
        signedAt: note.signedAt,
        dataPoints: [],
      };
      if (aiContent?.qualityMetrics) {
        contextData.qualityMetrics = aiContent.qualityMetrics;
      }
      if (aiContent?.codeSuggestions) {
        contextData.codeSuggestions = aiContent.codeSuggestions;
      }
      const patientId = note.patientId;
      if (patientId) {
        const [records, medications, appointments] = await Promise.all([
          storage.getHealthRecords(patientId),
          storage.getActiveMedicationReminders(patientId),
          storage.getUpcomingAppointments(patientId),
        ]);
        const recentLabs = records
          .filter((r: any) => r.type === "lab")
          .slice(0, 5)
          .map((r: any) => ({ label: r.title, value: r.summary, date: r.date, type: "lab" }));
        const recentVitals = records
          .filter((r: any) => r.type === "vital")
          .slice(0, 5)
          .map((r: any) => ({ label: r.title, value: r.summary, date: r.date, type: "vital" }));
        const activeMeds = medications.slice(0, 10).map((m: any) => ({
          label: m.medicationName,
          value: `${m.dosage || ""} ${m.frequency || ""}`.trim(),
          type: "medication",
        }));
        const upcomingAppts = appointments.slice(0, 3).map((a: any) => ({
          label: a.appointmentType || "Appointment",
          value: a.providerName || "Provider",
          date: a.scheduledAt,
          type: "appointment",
        }));
        contextData.dataPoints = [...recentLabs, ...recentVitals, ...activeMeds, ...upcomingAppts];
      }
      auditLog(req, "view_note_context", "ClinicalNote", (req.params as any).id);
      res.json(contextData);
    } catch (error) {
      console.error("Get note context error:", error);
      res.status(500).json({ error: "Failed to get note context" });
    }
  });


