  app.post("/api/document-generation/generate", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = req.headers["x-user-id"] as string;
      const { documentType, additionalContext, fields } = req.body as any;

      if (!documentType) {
        return res.status(400).json({ error: "documentType is required" });
      }

      const user = await storage.getUser(userId);
      const records = await storage.getHealthRecords(userId);

      const conditions = records.filter(r => r.type === "condition");
      const medications = records.filter(r => r.type === "medication");
      const vitals = records.filter(r => r.type === "vital").slice(0, 10);
      const labs = records.filter(r => r.type === "labs" || r.type === "lab").slice(0, 10);
      const allergies = records.filter(r => r.type === "allergy");
      const visits = records.filter(r => r.type === "visit").slice(0, 5);

      const patientData: any = {
        demographics: {
          name: user?.name || "Patient",
          age: 0,
          gender: "Not specified",
          dob: "Not specified",
          mrn: userId.substring(0, 8),
        },
        conditions: conditions.map(c => c.title || "Unknown condition"),
        medications: medications.map(m => ({
          name: m.title || "Unknown",
          dosage: m.summary || "",
          frequency: "",
          startDate: m.date ? new Date(m.date).toISOString().split("T")[0] : "Unknown",
        })),
        allergies: allergies.map(a => a.title || "Unknown"),
        vitals: vitals.map(v => ({
          type: v.title || "Unknown",
          value: 0,
          unit: "",
          date: v.date ? new Date(v.date).toISOString().split("T")[0] : "Unknown",
        })),
        labResults: labs.map(l => ({
          name: l.title || "Unknown",
          value: 0,
          unit: "",
          referenceRange: "",
          date: l.date ? new Date(l.date).toISOString().split("T")[0] : "Unknown",
          flag: "",
        })),
        treatmentHistory: [],
        recentVisits: visits.map(v => ({
          date: v.date ? new Date(v.date).toISOString().split("T")[0] : "Unknown",
          type: "Visit",
          provider: v.provider || "Unknown",
          summary: v.summary || v.title || "",
        })),
      };

      let result: any;

      if (documentType === "patient_summary") {
        result = await aiDocumentationAssistant.generatePatientSummary(patientData);
        result = {
          title: `Health Summary - ${user?.name || "Patient"}`,
          sections: [
            { heading: "Overview", content: result.summary, aiConfidence: 85, sources: ["health records"] },
            { heading: "Key Findings", content: result.keyFindings?.join("\n\n") || "No significant findings", aiConfidence: 80, sources: ["conditions", "labs"] },
            { heading: "Active Problems", content: result.activeProblems?.join("\n\n") || "None documented", aiConfidence: 85, sources: ["conditions"] },
            { heading: "Medications", content: result.medicationSummary || "No medications listed", aiConfidence: 90, sources: ["medications"] },
            { heading: "Risk Factors", content: result.riskFactors?.join("\n\n") || "None identified", aiConfidence: 75, sources: ["demographics", "conditions"] },
            { heading: "Preventive Care", content: result.preventiveCareGaps?.join("\n\n") || "Up to date", aiConfidence: 70, sources: ["immunizations", "labs"] },
          ],
          summary: result.summary,
          disclaimer: result.disclaimer,
          generatedAt: new Date().toISOString(),
        };
      } else if (documentType === "referral_letter") {
        const referralContext = {
          toSpecialty: fields?.toSpecialty || "General Specialist",
          reason: fields?.reason || "Clinical evaluation",
          urgency: fields?.urgency || "Routine",
          specificQuestions: fields?.reason ? [fields.reason] : ["Please evaluate and advise"],
        };
        const letterResult = await aiDocumentationAssistant.generateReferralLetter(patientData, referralContext);
        result = {
          title: `Referral Letter - ${referralContext.toSpecialty}`,
          sections: [
            { heading: "Referral Letter", content: letterResult.letter, aiConfidence: 85, sources: ["health records"] },
            { heading: "Suggested Attachments", content: letterResult.attachmentSuggestions?.join("\n") || "None", aiConfidence: 80, sources: [] },
            { heading: "Urgency Justification", content: letterResult.urgencyJustification || "Routine referral", aiConfidence: 85, sources: ["conditions"] },
          ],
          summary: `Referral to ${referralContext.toSpecialty} for ${referralContext.reason}`,
          disclaimer: "AI-generated documentation draft. Must be reviewed, verified, and signed by a licensed healthcare provider before use in clinical care. This is not medical advice.",
          generatedAt: new Date().toISOString(),
        };
      } else if (documentType === "lab_explanation") {
        const labContext = fields?.labContext || "";
        const draft = await aiDocumentationAssistant.generateDocumentDraft(
          patientData,
          "consultation",
          `Generate a patient-friendly explanation of lab results. Focus on what each result means in plain language, whether values are normal or abnormal, and what action if any may be needed. ${labContext}`,
          { enableCodingSuggestions: false, enableNextSteps: true, enableBenchmarkComparisons: false, includePatientEducation: true, noteStyle: "detailed" }
        );
        result = {
          title: "Lab Results Explanation",
          sections: draft.sections.map(s => ({
            heading: s.heading,
            content: s.content,
            aiConfidence: s.aiConfidence,
            sources: s.sources,
          })),
          summary: draft.summary,
          disclaimer: draft.disclaimer,
          generatedAt: new Date().toISOString(),
        };
      } else if (documentType === "medication_summary") {
        const draft = await aiDocumentationAssistant.generateDocumentDraft(
          patientData,
          "consultation",
          "Generate a comprehensive medication summary in patient-friendly language. For each medication, explain what it's for, how to take it, common side effects to watch for, and any important interactions. Include a section on general medication safety tips.",
          { enableCodingSuggestions: false, enableNextSteps: false, enableBenchmarkComparisons: false, includePatientEducation: true, noteStyle: "detailed" }
        );
        result = {
          title: "Medication Summary",
          sections: draft.sections.map(s => ({
            heading: s.heading,
            content: s.content,
            aiConfidence: s.aiConfidence,
            sources: s.sources,
          })),
          summary: draft.summary,
          disclaimer: draft.disclaimer,
          generatedAt: new Date().toISOString(),
        };
      } else if (documentType === "visit_summary") {
        const visitCtx = fields?.visitContext || "";
        const draft = await aiDocumentationAssistant.generateDocumentDraft(
          patientData,
          "progress_note",
          `Generate a patient-friendly visit summary. Summarize what was discussed, any new findings, changes to treatment, and next steps. ${visitCtx}`,
          { enableCodingSuggestions: false, enableNextSteps: true, enableBenchmarkComparisons: false, includePatientEducation: true, noteStyle: "detailed" }
        );
        result = {
          title: "Visit Summary",
          sections: draft.sections.map(s => ({
            heading: s.heading,
            content: s.content,
            aiConfidence: s.aiConfidence,
            sources: s.sources,
          })),
          summary: draft.summary,
          disclaimer: draft.disclaimer,
          generatedAt: new Date().toISOString(),
        };
      } else if (documentType === "health_letter") {
        const purpose = fields?.purpose || "general health status documentation";
        const draft = await aiDocumentationAssistant.generateDocumentDraft(
          patientData,
          "consultation",
          `Generate a formal health status letter for the following purpose: ${purpose}. The letter should be professional, suitable for submission to employers, insurers, or institutions. Include current health status, any relevant conditions under management, and a professional assessment.`,
          { enableCodingSuggestions: false, enableNextSteps: false, enableBenchmarkComparisons: false, includePatientEducation: false, noteStyle: "detailed" }
        );
        result = {
          title: `Health Status Letter - ${purpose}`,
          sections: draft.sections.map(s => ({
            heading: s.heading,
            content: s.content,
            aiConfidence: s.aiConfidence,
            sources: s.sources,
          })),
          summary: draft.summary,
          disclaimer: draft.disclaimer,
          generatedAt: new Date().toISOString(),
        };
      } else {
        return res.status(400).json({ error: `Unsupported document type: ${documentType}` });
      }

      auditLog(req, "patient_generate_document", "Document", documentType);
      res.json(result);
    } catch (error) {
      console.error("Patient document generation error:", error);
      res.status(500).json({ error: "Failed to generate document. Please try again." });
    }
  });

